mapper.select:
select news_seq as newsSeq, slug, title, category, summary, content, tags_json as tagsJson, source_url as sourcesJson, status, delete_flg as deleteFlg, date(published_dtm) as publishedDate, null as sourceFile, null as crawlError, reg_dtm as registeredAt, reg_id as registeredBy, mod_dtm as modifiedAt, mod_id as modifiedBy from bd_ai_news_mst where delete_flg = 'N' and status = 'Y'
and ( title like concat('%', #{keyword}, '%') or content like concat('%', #{keyword}, '%') )
order by published_dtm desc, news_seq desc limit #{limit}
